export type Level = 'foundational' | 'beginner' | 'intermediate' | 'advanced';

export interface Module {
  slug: string;
  title: string;
  icon: string;
  xp: number;
  readTime: number;
  desc: string;
  seoDesc: string;
  keywords: string;
  externalUrl?: string;
  /** Slugs de módulos que devem ser estudados antes deste. */
  prerequisites?: string[];
  /** Slugs de próximos passos sugeridos (pode atravessar trilhas). */
  nextSuggested?: string[];
  /** Nível de dificuldade didática. */
  level?: Level;
}

export interface Trail {
  id: string;
  name: string;
  color: string;
  icon: string;
  desc: string;
  unlockAfter?: string;
  modules: Module[];
  /** IDs de trilhas que idealmente vêm antes desta. */
  prerequisites?: string[];
  /** Nível da trilha como um todo. */
  level?: Level;
  /** Rota da trilha (ex: "/fundamentos-da-ia"). Usado por HomeClient/CommandPalette. */
  href?: string;
}

export interface Hub {
  id: string;
  slug: string;
  name: string;
  shortName: string;
  href: string;
  color: string;
  icon: string;
  tagline: string;
  desc: string;
  trailIds: string[];
}

